<x-plans-layout title="Checkout"><section class="glass-panel mx-auto max-w-lg rounded-[26px] p-6 text-center"><p class="text-[11px] font-semibold uppercase tracking-[0.32em] text-sb-accent">Secure checkout</p><h2 class="mt-2 text-2xl font-semibold text-stone-100">Opening Razorpay</h2><p class="mt-2 text-sm text-stone-500">Complete payment in the Razorpay window. Your plan activates only after the verified payment webhook arrives.</p><button id="open-checkout" class="mt-6 rounded-xl bg-sb-accent px-4 py-2 font-semibold text-sb-bg-dark">Open checkout</button></section><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>const options = { key: @json(config('services.razorpay.key_id')), amount: @json($transaction->amount), currency: 'INR', name: 'Second Brain', description: @json($transaction->plan->name), order_id: @json($transaction->razorpay_order_id), handler: () => window.location = @json(route('plans.index')), modal: { ondismiss: () => window.location = @json(route('plans.index')) } }; const checkout = new Razorpay(options); document.getElementById('open-checkout').addEventListener('click', () => checkout.open()); window.addEventListener('load', () => checkout.open());</script></x-plans-layout>
